require "yaml"
require "json"
require "date"
require "fileutils"

check = ARGV.delete("--check")
abort "Usage: ruby scripts/build_pseudo.rb [--check]" unless ARGV.empty?

root = File.expand_path("..", __dir__)
output = File.join(root, "pseudo")
FileUtils.mkdir_p(output)
header = { "format" => "micharisma-seeds/v1", "namespace" => "MIC", "catalog" => "ALA",
  "source" => { "note" => "Fictional leagues, people, contracts and schedules generated by scripts/build_pseudo.rb. No historical sports claims." } }
save = lambda do |path, contents|
  if check
    abort "Generated file differs: #{path}" unless File.file?(path) && File.read(path) == contents
  else
    File.write(path, contents)
  end
end
write = lambda do |name, records|
  document = JSON.parse(JSON.generate(header.merge("records" => records)))
  save.call(File.join(output, "#{name}.yml"), YAML.dump(document))
end
record = lambda do |type, code, attributes = {}, references = {}|
  { "type" => type, "code" => code, "attributes" => attributes, "references" => references }
end
foundation = [record.call("Country", "COUNTRY-US", { "name" => "United States", "abbreviation" => "US" })]
(2022..2024).each { |year| foundation << record.call("Year", "YEAR-#{year}", { "number" => year }) }
first_names = %w[Adrian Bennett Caleb Daniel Elias Felix Gabriel Hugo Isaac Julian Kai Luca Mateo Nolan Oliver Rafael Samuel Theo Victor Wesley Xavier Zachary Aaron Blake Colin Dorian Evan Finn Grant Henry Jonah Leon Miles Nico Owen Parker Quinn Rowan Silas Tobias Vincent Wyatt Andre Bruno Cedric Devin Emilio Francis Graham Harris Ivan Jasper Kieran Lionel Marcus Nathan Oscar Preston Reid Stefan Tristan Vaughn Warren Alistair Brody Cyrus Damian Enzo Fraser Gavin Heath Iker Jonas Kendrick Landon Milan Noel Orion Pierce Remy Soren Tomas Uriel Valentin Wilfred Alexis Bowen Cillian Dante Ewan Florian Gideon Holden Idris Jalen Keaton Leander Marcel Niall Otis Pascal Reuben Stellan Torin Ulises Vance Winston Abel Byron Callum Dario Emmett Fabian Griffin Henrik Ira Jericho Knox Lucian Malcolm Neil Omar Phoenix Ronan Sullivan Tate Urban Vernon Wallace]
last_names = %w[Alvarez Bennett Carter Duarte Ellis Fischer Grant Haddad Ito Jensen Kim Laurent Moreno Novak Okafor Pereira Quinn Rossi Silva Torres Usman Vega Walker Xu Young Zimmer Anders Brooks Costa Delgado Evans Foster Green Hayes Inoue Jones Keller Lewis Martin Nguyen Ortiz Patel Reed Santos Turner Valdez Wright Yang Zuniga Archer Bell Cruz Diaz Edwards Flores Garcia Hughes Ibrahim James Khan Lopez Miller Nash Olsen Price Rivera Scott Thomas Vasquez White Yates Abbott Bailey Clark Davis Elliott Ford Gomes Howard Irwin Johnson Kelly Lane Morgan Nelson Owen Parker Ramos Shaw Taylor Vaughan Wilson York Adams Blake Cole Dunn Eaton Finch Gray Hill Ivers King Lowe Moss North Page Ross Stone Tate Vale Ward West Zane]
teams = [
  ["Briarfield", "Foxes", "BRI"], ["Cedarport", "Pilots", "CED"], ["Fairhaven", "Herons", "FAI"], ["Glenford", "Stags", "GLE"],
  ["Kingswell", "Owls", "KIN"], ["Lakebridge", "Otters", "LAK"], ["Northwick", "Falcons", "NOR"], ["Rivermere", "Wolves", "RIV"]
]
leagues = [
  ["BKT", "Basketball", "Horizon Basketball League", "HBL", %w[PG SG SF PF C PG SG SF PF C SG SF], 3],
  ["HCK", "Hockey", "Northern Ice League", "NIL", %w[C LW RW D D C LW RW D D C LW RW D D C LW RW D D G G G G], 3],
  ["SOC", "Soccer", "Riverside Football League", "RFL", %w[GK GK GK CB CB CB CB LB LB RB RB DM DM CM CM AM AM LW LW RW RW ST ST], 1]
]
counts = Hash.new(0)
leagues.each_with_index do |(sport, sport_name, league_name, abbreviation, positions, best_of), league_index|
  prefix = "PSEUDO-#{abbreviation}"
  league = "#{prefix}-LEAGUE"
  anchors = [record.call("Sport", "SPORT-#{sport}", { "name" => sport_name }),
    record.call("League", league, { "name" => league_name, "abbreviation" => abbreviation }, { "sport" => "SPORT-#{sport}", "jurisdiction" => "COUNTRY-US" })]
  2.times do |conference|
    conf = "#{prefix}-CONFERENCE-#{conference + 1}"
    anchors << record.call("Conference", conf, { "name" => %w[Eastern Western][conference], "abbreviation" => %w[E W][conference] }, { "league" => league })
    2.times do |division|
      index = conference * 2 + division
      anchors << record.call("Division", "#{prefix}-DIVISION-#{index + 1}", { "name" => %w[Coastal Highland Valley Lakes][index], "abbreviation" => "D#{index + 1}" }, { "conference" => conf })
    end
  end
  teams.each_with_index do |(territory, mascot, short), index|
    team = "#{prefix}-TEAM-#{short}"
    org = "#{prefix}-ORG-#{short}"
    anchors << record.call("Team", team, { "territory" => territory, "mascot" => mascot, "abbreviation" => short }, { "league" => league })
    anchors << record.call("Organization", org, { "name" => "#{territory} #{mascot} Club", "abbreviation" => short })
    anchors << record.call("OrganizationAffiliation", "#{org}-AFFILIATION", { "start_date" => "2022-01-01", "details" => { "relationship" => "senior_team" } }, { "organization" => org, "team" => team })
    positions.each_with_index do |position, slot|
      player_index = index * positions.length + slot
      name_index = league_index * 200 + player_index
      anchors << record.call("Player", "#{prefix}-PLAYER-#{player_index + 1}", {
        "first_name" => first_names[name_index % first_names.length],
        "last_name" => last_names[(name_index * 37 + name_index / first_names.length) % last_names.length],
        "birthdate" => Date.new(1988 + player_index % 15, 1 + player_index % 12, 1 + player_index % 28).iso8601,
        "current_position" => position, "debut_year" => 2022, "active" => true
      }, { "sport" => "SPORT-#{sport}" })
    end
  end
  write.call("#{abbreviation.downcase}_foundation", anchors)
  anchors.each { |entry| counts[entry.fetch("type")] += 1 }

  (2022..2024).each do |year|
    season = "#{prefix}-SEASON-#{year}"
    start_date = Date.new(year, 2, 5)
    regular_end = start_date + 13 * 7
    end_date = Date.new(year, 6, 25)
    regular = "#{season}-REGULAR"
    playoffs = "#{season}-PLAYOFFS"
    records = [record.call("Season", season, {
      "label" => year.to_s, "start_date" => start_date.iso8601, "end_date" => regular_end.iso8601,
      "playoff_start_date" => "#{year}-06-01", "playoff_end_date" => end_date.iso8601
    }, { "league" => league, "year" => "YEAR-#{year}" })]
    campaigns = teams.map { |_, _, short| "#{season}-TEAM-#{short}" }
    teams.each_with_index do |(territory, mascot, short), index|
      team = "#{prefix}-TEAM-#{short}"
      campaign = campaigns[index]
      records << record.call("Campaign", campaign, { "display_name" => "#{territory} #{mascot}", "abbreviation" => short,
        "details" => { "roster_coverage" => "complete_generated_roster" } }, {
        "team" => team, "season" => season, "conference" => "#{prefix}-CONFERENCE-#{index / 4 + 1}", "division" => "#{prefix}-DIVISION-#{index / 2 + 1}"
      })
      positions.each_with_index do |_, slot|
        origin = slot < 2 ? (index - (year - 2022)) % teams.length : index
        player = "#{prefix}-PLAYER-#{origin * positions.length + slot + 1}"
        contract = "#{campaign}-CONTRACT-#{slot + 1}"
        dates = { "start_date" => "#{year}-01-01", "end_date" => "#{year}-12-31" }
        records << record.call("Contract", contract, dates.merge("total_dollar_value" => 150000 + slot * 50000), {
          "player" => player, "team" => team, "organization" => "#{prefix}-ORG-#{short}"
        })
        records << record.call("Activation", "#{campaign}-ACTIVATION-#{slot + 1}", dates, { "player" => player, "campaign" => campaign, "contract" => contract })
        records << record.call("Stint", "#{campaign}-STINT-#{slot + 1}", dates, { "player" => player, "team" => team, "contract" => contract })
      end
    end
    records << record.call("Contest", regular, { "name" => "#{year} #{league_name} regular season", "kind" => "regular_season",
      "begin_date" => start_date.iso8601, "end_date" => regular_end.iso8601,
      "format_rules" => { "schedule" => "double_round_robin", "points_for_win" => 3, "points_for_draw" => 1 }
    }, { "context" => league, "season" => season })
    campaigns.each_with_index do |campaign, index|
      records << record.call("Contestant", "#{regular}-ENTRY-#{index + 1}", {}, { "contest" => regular, "campaign" => campaign })
    end
    points = Array.new(teams.length, 0)
    add_game = lambda do |code, competition, date, home, away, home_score, away_score, metadata|
      records << record.call("Game", code, { "name" => "#{teams[away][0]} #{teams[away][1]} at #{teams[home][0]} #{teams[home][1]}",
        "begin_date" => date.iso8601, "end_date" => date.iso8601, "details" => { "venue" => "#{teams[home][0]} Arena" }
      }, { "context" => league, "season" => season })
      [[home, home_score, "home"], [away, away_score, "away"]].each do |team_index, score, side|
        records << record.call("Contestant", "#{code}-ENTRY-#{side.upcase}", { "tiebreakers" => { "side" => side, "score" => score } }, { "contest" => code, "campaign" => campaigns[team_index] })
      end
      records << record.call("ContestGame", "#{code}-MEMBERSHIP", { "metadata" => metadata }, { "contest" => competition, "game" => code })
    end
    rotation = (0...teams.length).to_a
    7.times do |round|
      4.times do |pair|
        left, right = rotation[pair], rotation[-pair - 1]
        2.times do |leg|
          home, away = (round + pair + leg).even? ? [left, right] : [right, left]
          week = round + leg * 7
          raw_home = (home * 7 + away * 3 + week + year) % 5
          raw_away = (away * 5 + home * 2 + week + year) % 5
          raw_home += 1 if sport != "SOC" && raw_home == raw_away
          scores = sport == "BKT" ? [80 + raw_home * 7, 80 + raw_away * 7] : [raw_home, raw_away]
          if scores[0] == scores[1]
            points[home] += 1
            points[away] += 1
          else
            points[scores[0] > scores[1] ? home : away] += 3
          end
          add_game.call("#{season}-GAME-W#{week + 1}-#{pair + 1}", regular, start_date + week * 7,
            home, away, *scores, { "matchweek" => week + 1 })
        end
      end
      rotation = [rotation.first, rotation.last, *rotation[1...-1]]
    end
    ranked = (0...teams.length).sort_by { |index| [-points[index], index] }
    records.select { |entry| entry["code"].start_with?("#{regular}-ENTRY-") }.each do |entry|
      team_index = entry["code"].split("-").last.to_i - 1
      entry["attributes"] = { "placing" => ranked.index(team_index) + 1, "tiebreakers" => { "points" => points[team_index] } }
    end
    records << record.call("Contest", playoffs, { "name" => "#{year} #{league_name} playoffs", "kind" => "playoffs",
      "begin_date" => "#{year}-06-01", "end_date" => end_date.iso8601,
      "format_rules" => { "rounds" => [{ "key" => "semifinal", "name" => "Semifinals", "best_of" => best_of }, { "key" => "final", "name" => "Final", "best_of" => best_of }],
        "qualification" => "top_four", "table_tiebreaker" => "team_code" }
    }, { "context" => league, "season" => season })
    ranked.first(4).each do |index|
      records << record.call("Contestant", "#{playoffs}-ENTRY-#{index + 1}", {}, { "contest" => playoffs, "campaign" => campaigns[index] })
    end
    [["semifinal", ranked[0], ranked[3], 1], ["semifinal", ranked[1], ranked[2], 2], ["final", ranked[0], ranked[1], 1]].each do |round, winner, loser, series|
      best_of.times do |game_index|
        home, away = game_index.odd? ? [loser, winner] : [winner, loser]
        winning_team = best_of == 3 && game_index == 1 ? loser : winner
        winning_score, losing_score = sport == "BKT" ? [104, 96] : [3, 1]
        scores = home == winning_team ? [winning_score, losing_score] : [losing_score, winning_score]
        date = Date.new(year, 6, round == "final" ? 15 : 1) + game_index * 3
        add_game.call("#{playoffs}-#{round.upcase}-#{series}-GAME-#{game_index + 1}", playoffs, date,
          home, away, *scores, { "round" => round, "series" => "#{round}-#{series}", "game_number" => game_index + 1 })
      end
    end
    records << record.call("TitleAward", "#{season}-TABLE-TITLE", { "key" => "league_table", "name" => "#{league_name} Table Trophy", "awarded_on" => regular_end.iso8601 }, { "contest" => regular, "winner" => "#{regular}-ENTRY-#{ranked[0] + 1}" })
    records << record.call("TitleAward", "#{season}-PLAYOFF-TITLE", { "key" => "playoff_champion", "name" => "#{league_name} Championship", "awarded_on" => (Date.new(year, 6, 15) + (best_of - 1) * 3).iso8601 }, { "contest" => playoffs, "winner" => "#{playoffs}-ENTRY-#{ranked[0] + 1}" })
    write.call("#{abbreviation.downcase}_#{year}", records)
    records.each { |entry| counts[entry.fetch("type")] += 1 }
  end
end
write.call("foundation", foundation)
foundation.each { |entry| counts[entry.fetch("type")] += 1 }
save.call(File.join(output, "entity_sequences.yaml"), File.read(File.join(root, "yaml/entity_sequences.yaml")))
puts JSON.pretty_generate(counts.sort.to_h)
